package com.bank.history.dto;

import java.time.LocalDate;

// The "last seen" position. The client sends this back to get the next page.
public class PageCursor {
    private final LocalDate lastTxnDate;
    private final long lastTxnId;

    public PageCursor(LocalDate lastTxnDate, long lastTxnId) {
        this.lastTxnDate = lastTxnDate;
        this.lastTxnId = lastTxnId;
    }
    public LocalDate getLastTxnDate() { return lastTxnDate; }
    public long getLastTxnId() { return lastTxnId; }
}
