package com.bank.history.repository;

import com.bank.history.model.Transaction;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.time.LocalDate;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, Long> {

    // KEYSET: row-value comparison on (txn_date, txn_id) uses idx_hist_keyset.
    // Seeks directly to the cursor — same speed at any depth.
    @Query("SELECT t FROM Transaction t WHERE t.accountId = :acct " +
           "AND (t.txnDate > :lastDate OR (t.txnDate = :lastDate AND t.txnId > :lastId)) " +
           "ORDER BY t.txnDate, t.txnId")
    List<Transaction> nextPage(@Param("acct") String acct,
                               @Param("lastDate") LocalDate lastDate,
                               @Param("lastId") long lastId,
                               Pageable limit);

    // First page (no cursor yet)
    @Query("SELECT t FROM Transaction t WHERE t.accountId = :acct ORDER BY t.txnDate, t.txnId")
    List<Transaction> firstPage(@Param("acct") String acct, Pageable limit);
}
