package com.bank.history.service;

import com.bank.history.dto.PageCursor;
import com.bank.history.model.Transaction;
import com.bank.history.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class TransactionHistoryService {
    private static final Logger log = LoggerFactory.getLogger(TransactionHistoryService.class);
    private final TransactionRepository repo;

    public TransactionHistoryService(TransactionRepository repo) { this.repo = repo; }

    // Keyset pagination: pass null cursor for the first page, then the returned cursor onward.
    public List<Transaction> page(String accountId, PageCursor cursor, int size) {
        List<Transaction> rows;
        if (cursor == null) {
            rows = repo.firstPage(accountId, PageRequest.of(0, size));
            log.info("First page for {} ({} rows)", accountId, rows.size());
        } else {
            rows = repo.nextPage(accountId, cursor.getLastTxnDate(),
                                 cursor.getLastTxnId(), PageRequest.of(0, size));
            log.info("Next page for {} after ({}, {}) — seek, not scan",
                     accountId, cursor.getLastTxnDate(), cursor.getLastTxnId());
        }
        return rows;
    }
}
